entries[472324] = { ["name"] = "Heulen des Rudelführers", ["text"] = "Sofort\nIm Kampf beschwört Euer nächster 'Tötungsbefehl' alle 30 Sek. die Hilfe eines Wildtiers.\n\nWyvern\nEin Wyvern stürzt sich vom Himmel herab und stößt einen Kampfesschrei aus, der Euren Schaden sowie den Eurer Begleiter 15 Sek. lang um 10% erhöht.\n\nEber\nEin Eber stürmt 3-mal durch die gegnerischen Reihen und fügt dem Hauptziel (400% der Angriffskraft) körperlichen Schaden sowie bis zu 8 Gegnern in der Nähe (160% der Angriffskraft) Schaden zu.\n\nBär\nEin Bär stürzt sich ins Getümmel, reißt den Gegnern das Fleisch von den Knochen und fügt so bis zu 8 Gegnern in der Nähe im Verlauf von 10 Sek. (400% der Angriffskraft) Schaden zu." }
entries[472325] = { ["name"] = "Heulen des Rudelführers", ["text"] = "Sofort\nIm Kampf beschwört Euer nächster 'Tötungsbefehl' alle 30 Sek. die Hilfe eines Wildtiers.\n\nWyvern\nEin Wyvern stürzt sich vom Himmel herab und stößt einen Kampfesschrei aus, der Euren Schaden sowie den Eurer Begleiter 15 Sek. lang um 10% erhöht.\n\nEber\nEin Eber stürmt 3-mal durch die gegnerischen Reihen und fügt dem Hauptziel (400% der Angriffskraft) körperlichen Schaden sowie bis zu 8 Gegnern in der Nähe (160% der Angriffskraft) Schaden zu.\n\nBär\nEin Bär stürzt sich ins Getümmel, reißt den Gegnern das Fleisch von den Knochen und fügt so bis zu 8 Gegnern in der Nähe im Verlauf von 10 Sek. (400% der Angriffskraft) Schaden zu." }
