entries[472357] = { ["name"] = "Gemeinsam besser", ["text"] = "Tierherrschaft\nDer verursachte Schaden Eurer Begleiter ist um 3% erhöht.\n\nDer Angriffsgeschwindigkeitsbonus von 'Raserei' ist 3% stärker.\n\nÜberleben\nDer verursachte Schaden Eures Begleiters ist um 15% erhöht.\n\nDer Schaden von 'Speerspitze' ist um 15% erhöht." }
entries[472358] = { ["name"] = "Rudelverhalten", ["text"] = "Tierherrschaft\nDie Fähigkeit 'Heulen des Rudelführers' erhöht den Schaden von 'Tötungsbefehl' um 50%.\n\nDas Beschwören eines Wildtiers verringert die Abklingzeit von 'Stachelpfeil' um 10.0 Sek.\n\nÜberleben\nDie Fähigkeit 'Heulen des Rudelführers' lässt Euren 'Tötungsbefehl' einen zusätzlichen Stapel von 'Speerspitze' erzeugen.\n\nDas Beschwören eines Wildtiers verringert die Abklingzeit von 'Lauffeuerbombe' um 10.0 Sek." }
entries[472360] = { ["name"] = "Laterne des verlorenen Vrykul", ["text"] = "Sofort\nDer Einsatz Eurer zentralen Klassenfähigkeit mit Abklingzeit erfüllt Euch mit der Wildheit von Vrykulseelen und erhöht Euren kritischen Trefferwert 8 Sek. lang um 137 .\n\nAbhängig davon, wann Ihr zuletzt erfüllt wurdet, hält der Effekt bis zu 40 Sek. länger an." }
