entries[472741] = { ["name"] = "Mit gutem Beispiel voran", ["text"] = "Überleben\nDer Einsatz von 'Koordinierter Angriff' gewährt 'Heulen des Rudelführers' und erhöht den Schaden Eurer Wildtiere um 25% und den Schaden Eures Begleiters um 30%. Hält 12 Sek. lang an.\n\nTierherrschaft\nDer Einsatz von 'Zorn des Wildtiers' gewährt 'Heulen des Rudelführers' und erhöht den Schaden Eurer Wildtiere um 25% und den Schaden Eurer Begleiter um 15%. Hält 12 Sek. lang an.\n\n(700ms Abklingzeit)" }
