entries[472898] = { ["name"] = "Wundgift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort (4.07% der Angriffskraft) Naturschaden verursacht und 12 Sek. lang sämtliche erhaltene Heilung um 8% verringert. Dieser Effekt ist bis zu 3-mal stapelbar." }
entries[472899] = { ["name"] = "Wundgift", ["text"] = "Wirken in 1.5 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort (4.07% der Angriffskraft) Naturschaden verursacht und 12 Sek. lang sämtliche erhaltene Heilung um 8% verringert. Dieser Effekt ist bis zu 3-mal stapelbar.\n(Procchance: 30%)" }
entries[472901] = { ["name"] = "Verkrüppelndes Gift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht eine Waffe mit Gift, das eine Stunde lang an ihr haften bleibt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften und seine Bewegungsgeschwindigkeit 12 Sek. lang um 50% zu verringern." }
entries[472902] = { ["name"] = "Verkrüppelndes Gift", ["text"] = "Wirken in 1.5 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem nichttödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was seine Bewegungsgeschwindigkeit für 12 Sek. um 50% verringert.\n(Procchance: 30%)" }
