entries[473153] = { ["name"] = "Zerhäckseln", ["text"] = "25 Energie / 1 zu 7 Combopunkte 100 Meter Reichweite\nSofort\nFinishing-Move, der Combopunkte verbraucht, um das Angriffstempo um 50% zu erhöhen. Hält pro Combopunkt länger an:\n1 Punkt: 12 Sek.\n2 Punkte: 18 Sek.\n3 Punkte: 24 Sek.\n4 Punkte: 30 Sek.\n5 Punkte: 36 Sek.\n[ 6 Punkte: 42 Sek.] [ 7 Punkte: 48 Sek.]" }
