entries[473325] = { ["name"] = "Notizen machen", ["text"] = "Sofort\nDiese Option ermöglicht, dass die Irdenen den Splitter ohne Eure Hilfe reparieren, aber Ihr müsst dann warten, bis sie mit der Arbeit fertig sind.\n\nDas ist nicht notwendig, um diese Quest abzuschließen.\n\nDiese Option wählen?" }
